const std::array<VehicleVector, 4> &trail_shape(const TrailProfileBank &bank, std::uint32_t identity)
{
    if (!identity)
        throw FormatError("screen trail has no world shape");
    const TrailShape *found = nullptr;
    for (const auto &shape : bank.shapes)
        if (shape.identity == identity)
        {
            if (found)
                throw FormatError("duplicate trail shape identity");
            found = &shape;
        }
    if (!found)
        throw FormatError("unresolved trail shape identity");
    return found->points;
}
